    { id: "svichka", uk: "свічка", tr: "SVICH-ka", en: "candle", ic: "🕯️", acc: "свічку" },
    { id: "hlechyk", uk: "глечик", tr: "HLE-chyk", en: "clay jug", ic: "🏺", fact: { uk: "Глечики сушили на тину.", en: "Clay jugs were hung upside down on village fences to dry." } },
    { id: "dzerkalo", uk: "дзеркало", tr: "DZER-ka-lo", en: "mirror", ic: "🪞" },
    { id: "hodynnyk", uk: "годинник", tr: "ho-DYN-nyk", en: "clock", ic: "🕰️" },
    { id: "pich", uk: "піч", tr: "pich", en: "stove", ic: "@stove", fact: { uk: "Піч гріє хату. У ній печуть хліб.", en: "The big clay stove was the heart of the home: it baked the bread, warmed the house, and people slept on top of it." } },
    { id: "rushnyk", uk: "рушник", tr: "rush-NYK", en: "embroidered towel", ic: "@rushnyk", fact: { uk: "Хліб і сіль зустрічають гостей на рушнику.", en: "Guests are welcomed with bread and salt held on an embroidered towel." } },
    { id: "chashka", uk: "чашка", tr: "CHASH-ka", en: "cup", ic: "☕", acc: "чашку" },
    { id: "kvity", uk: "квіти", tr: "KVI-ty", en: "flowers", ic: "💐" },
    { id: "polytsia", uk: "полиця", tr: "po-LY-tsia", en: "shelf", ic: "@shelf", acc: "полицю" },
    // --- Ukrainian culture
    { id: "pysanka", uk: "писанка", tr: "py-SAN-ka", en: "painted Easter egg", ic: "@pysanka", acc: "писанку", fact: { uk: "Писанки малюють воском і фарбами на Великдень.", en: "Pysanky are eggs painted with wax and dyes at Easter. Every pattern has a meaning." } },
    { id: "kalyna", uk: "калина", tr: "ka-LY-na", en: "viburnum (red berries)", ic: "@kalyna", acc: "калину", fact: { uk: "Калина — символ України. Про неї співають у піснях.", en: "Kalyna, the red viburnum, is a symbol of Ukraine. It appears in songs and embroidery." } },
    { id: "bandura", uk: "бандура", tr: "ban-DU-ra", en: "bandura (folk instrument)", ic: "@bandura", acc: "бандуру", fact: { uk: "Кобзарі грали на бандурі й співали давні пісні.", en: "Kobzars, travelling singers, played the bandura and sang old epic songs." } },
    { id: "korovai", uk: "коровай", tr: "ko-ro-VAI", en: "festive bread", ic: "@korovai", fact: { uk: "Коровай печуть на весілля.", en: "Korovai is a rich round bread baked for weddings, decorated with dough flowers and birds." } },
    { id: "didukh", uk: "дідух", tr: "di-DUKH", en: "Christmas wheat sheaf", ic: "@didukh", fact: { uk: "Дідух стоїть у хаті на Різдво.", en: "A didukh, a sheaf of wheat, stands in the home at Christmas to honour the ancestors and the harvest." } },
    { id: "malva", uk: "мальва", tr: "MAL-va", en: "hollyhock", ic: "@malva", acc: "мальву", fact: { uk: "Мальви ростуть біля сільських хат.", en: "Hollyhocks grow beside village cottages, and they are painted in folk art." } },
    { id: "vyshyvanka", uk: "вишиванка", tr: "vy-shy-VAN-ka", en: "embroidered shirt", ic: "@vyshyvanka", acc: "вишиванку", fact: { uk: "Кожен край має свою вишивку.", en: "Every region has its own embroidery. Vyshyvanka Day is in May." } },
    { id: "vinok", uk: "вінок", tr: "vi-NOK", en: "flower wreath", ic: "@vinok", fact: { uk: "Вінок із квітів і стрічок носять на свято.", en: "Wreaths of flowers and ribbons are worn at festivals and weddings." } },
    { id: "mak", uk: "мак", tr: "mak", en: "poppy", ic: "@mak", fact: { uk: "Мак часто вишивають і малюють.", en: "Poppies are embroidered and painted in folk art, and their seeds go into sweet rolls." } },
    { id: "pshenytsia", uk: "пшениця", tr: "psheh-NY-tsia", en: "wheat", ic: "@pshenytsia", acc: "пшеницю", fact: { uk: "Золоті поля пшениці — символ України.", en: "Ukraine is famous for its wheat. Golden fields under a blue sky are a symbol of the country." } },
    { id: "tarilka", uk: "тарілка", tr: "ta-RIL-ka", en: "painted plate", ic: "@tarilka", acc: "тарілку", fact: { uk: "Петриківський розпис — це яскраві квіти.", en: "Petrykivka painting, full of bright flowers, is a folk art that UNESCO listed in 2013." } },
    { id: "paska", uk: "паска", tr: "PAS-ka", en: "Easter bread", ic: "@paska", acc: "паску", fact: { uk: "Паску печуть на Великдень.", en: "Paska is a tall Easter bread. It is blessed in church in a basket with painted eggs." } },
    { id: "motanka", uk: "мотанка", tr: "mo-TAN-ka", en: "rag doll", ic: "@motanka", acc: "мотанку", fact: { uk: "Мотанка — лялька без обличчя.", en: "The motanka is a rag doll with no face, made as a lucky charm for children." } },
    { id: "chornobryvtsi", uk: "чорнобривці", tr: "chor-no-BRYV-tsi", en: "marigolds", ic: "@chornobryvtsi", fact: { uk: "Чорнобривці ростуть біля кожної хати.", en: "Marigolds are planted by nearly every village home. A well-known song about them remembers a mother's garden." } },
    { id: "tyn", uk: "тин", tr: "tyn", en: "wattle fence", ic: "@tyn", fact: { uk: "Тин плетуть із лози.", en: "A tyn is a fence woven from willow branches. Clay jugs are hung on its stakes to dry." } },
    { id: "prapor", uk: "прапор", tr: "PRA-por", en: "flag", ic: "@prapor", fact: { uk: "Синє небо і жовта пшениця.", en: "The blue and yellow of Ukraine's flag stand for the sky above a field of wheat." } },
    { id: "lastivka", uk: "ластівка", tr: "LAS-tiv-ka", en: "swallow", ic: "@lastivka", acc: "ластівку", fact: { uk: "«Щедрик» — пісня про ластівку.", en: "The carol Shchedryk tells of a swallow bringing good news. The world knows its tune as Carol of the Bells." } },
    { id: "skrynia", uk: "скриня", tr: "SKRY-nia", en: "painted chest", ic: "@skrynia", acc: "скриню", fact: { uk: "У скрині зберігали вишиванки й рушники.", en: "A painted wooden chest held a family's embroidered shirts and towels. A bride brought hers to her new home." } },
    // --- for the cats
    { id: "kihtetochka", uk: "кігтеточка", tr: "kih-te-TOCH-ka", en: "cat tree", ic: "@cattree", acc: "кігтеточку" },
    { id: "lezhanka", uk: "лежанка", tr: "le-ZHAN-ka", en: "cat bed", ic: "@catbed", acc: "лежанку" },
    { id: "miachyk", uk: "м'ячик", tr: "MIA-chyk", en: "little ball", ic: "@ball" },
    { id: "myshka", uk: "мишка", tr: "MYSH-ka", en: "toy mouse", ic: "@toymouse", acc: "мишку" },
    // --- tools and things you carry
    { id: "nasinnia", uk: "насіння", tr: "na-SIN-nia", en: "seeds", ic: "🌱" },
    { id: "vudka", uk: "вудка", tr: "VUD-ka", en: "fishing rod", ic: "@rod", acc: "вудку" },
    // Clothes for her wardrobe: whole outfits, each named for its main piece.
    { id: "shafa", uk: "шафа", tr: "SHA-fa", en: "wardrobe", ic: "@shafa" },
    { id: "sorochka", uk: "сорочка", tr: "so-ROCH-ka", en: "embroidered blouse", ic: "@o_sorochka", fact: { uk: "Вишита сорочка — найулюбленіший одяг в Україні.", en: "An embroidered blouse is Ukraine's best-loved piece of clothing." } },
    { id: "kersetka", uk: "керсетка", tr: "ker-SET-ka", en: "embroidered vest", ic: "@o_kersetka", fact: { uk: "Керсетку вдягали поверх сорочки на свята.", en: "A kersetka is a fitted sleeveless vest worn over the blouse on feast days." } },
    { id: "plakhta", uk: "плахта", tr: "PLAKH-ta", en: "checked wrap skirt", ic: "@o_plakhta", fact: { uk: "Плахту ткали з вовни, у клітинку.", en: "A plakhta is a wrap skirt woven from wool in a bright check." } },
    { id: "fartukh", uk: "фартух", tr: "FAR-tukh", en: "apron", ic: "@o_fartukh" },
    { id: "strichky", uk: "стрічки", tr: "STRICH-ky", en: "ribbons", ic: "@o_strichky", fact: { uk: "До вінка пришивали довгі кольорові стрічки.", en: "Long coloured ribbons were sewn to the back of a flower crown." } },
    { id: "plashch", uk: "плащ", tr: "plashch", en: "raincoat", ic: "@o_plashch" },
    { id: "puhovyk", uk: "пуховик", tr: "pu-kho-VYK", en: "winter parka", ic: "@o_puhovyk" },
    { id: "sarafan", uk: "сарафан", tr: "sa-ra-FAN", en: "sarafan (summer dress)", ic: "@o_sarafan" },
    { id: "kozhushok", uk: "кожушок", tr: "ko-zhu-SHOK", en: "sheepskin coat", ic: "@o_kozhushok", fact: { uk: "Кожушок шили з овечої шкури: у ньому тепло взимку.", en: "A kozhushok is a short sheepskin coat: warm all winter." } },
    // Wildlife through the year, and the weather
    { id: "hnizdo", uk: "гніздо", tr: "HNIZ-do", en: "nest", ic: "@hnizdo" },
    { id: "zhuravel", uk: "журавель", tr: "zhu-RA-vel", en: "crane (the bird)", ic: "@zhuravel", fact: { uk: "Восени журавлі ключем летять у вирій.", en: "In autumn cranes fly south in a V, which Ukrainians call a «key» (ключ)." } },
    { id: "yizhak", uk: "їжак", tr: "yi-ZHAK", en: "hedgehog", ic: "@yizhak", fact: { uk: "Узимку їжак спить у купі листя.", en: "In winter the hedgehog sleeps in a pile of leaves until spring." } },
    { id: "synytsia", uk: "синиця", tr: "sy-NY-tsia", en: "blue tit", ic: "@synytsia" },
    { id: "snihur", uk: "снігур", tr: "sni-HUR", en: "bullfinch", ic: "@snihur", fact: { uk: "Снігурі прилітають зі снігом.", en: "Bullfinches arrive with the snow: their name comes from сніг, snow." } },
    { id: "hodivnychka", uk: "годівничка", tr: "ho-div-NYCH-ka", en: "bird feeder", ic: "@hodivnychka" },
    { id: "hroza", uk: "гроза", tr: "hro-ZA", en: "thunderstorm", ic: "⛈️" },
    { id: "blyskavka", uk: "блискавка", tr: "BLYS-kav-ka", en: "lightning", ic: "⚡" },
    { id: "hrim", uk: "грім", tr: "hrim", en: "thunder", ic: "🌩️" },
    { id: "veselka", uk: "веселка", tr: "ve-SEL-ka", en: "rainbow", ic: "🌈", fact: { uk: "Після дощу виходить веселка.", en: "After the rain comes a rainbow." } },
    { id: "tuman", uk: "туман", tr: "tu-MAN", en: "fog, mist", ic: "🌫️" },
    { id: "snizhka", uk: "сніжка", tr: "SNIZH-ka", en: "snowball", ic: "@snizhka" },
    { id: "lodobur", uk: "льодобур", tr: "lo-do-BUR", en: "ice auger", ic: "@lodobur", fact: { uk: "Льодобуром свердлять лунку в льоду, щоб рибалити взимку.", en: "With an ice auger you drill a hole in the ice, so you can fish in winter." } },
    { id: "liika", uk: "лійка", tr: "LIY-ka", en: "watering can", ic: "@can", acc: "лійку" },
    { id: "koshyk", uk: "кошик", tr: "KO-shyk", en: "basket", ic: "@koshyk" },
    { id: "hroshi", uk: "гроші", tr: "HRO-shi", en: "money", ic: "💰" }
