  // Grandma Olia's cooking. She asks for each ingredient in turn, then cooks the dish and you eat together.
  // The village's festivals, in turn. The notice board lists what the village still needs; bring it all and
  // the festival begins: greetings, a round dance, and a festival finish.
  // Each festival has its own song (music/fest-<id>.mp3); beat and first are the dance beat measured from it, in seconds.
  festivals: [
    { id: "obzhynky", culture: "Obzhynky is the feast at the end of the grain harvest, in late summer. The reapers leave the last few stalks standing, or weave them into a harvest wreath of wheat and flowers, and carry it with songs to the farmer's house, where a loaf from the new grain is shared. The last sheaf is often kept until Christmas, when it becomes the didukh.", tune: "fest-obzhynky", beat: 0.8, first: 0.081, needs: { pshenytsia: 5, khlib: 2, yabluko: 4, kvitka: 3 }, greet: "zi_sviatom", reply: "zi_sviatom", center: "harvest", sky: "gold", reward: "didukh" },
    { id: "kupala", culture: "Ivana Kupala, or Kupala Night, is kept around midsummer, on the night of 6 to 7 July. Young people jump over bonfires for health and luck, girls float flower wreaths with candles down the river (whoever finds one, the story goes, will marry the girl who made it), and everyone searches the woods for the fern flower, said to bloom on this one night only.", tune: "fest-kupala", beat: 0.7895, first: 0.035, needs: { kvitka: 5, kalyna: 3, soniashnyk: 2 }, greet: "zi_sviatom", reply: "zi_sviatom", center: "fire", sky: "night", reward: "vinok", finale: "stryby" },
    { id: "sviatvechir", culture: "Sviat Vechir, Holy Evening, is Christmas Eve, now kept on 24 December. The family waits for the first star before sitting down to twelve meatless dishes, beginning with kutia, wheat with poppy seed and honey. A didukh, a sheaf of wheat for the family's ancestors, stands in the corner, and carollers go from house to house singing koliadky with a star on a pole, sometimes with someone dressed as a goat, the «koza».", tune: "fest-sviatvechir", beat: 0.8122, first: 0.07, needs: { kutia: 1, uzvar: 1, med: 2, mak: 3 }, greet: "khrystos_narodyvsia", reply: "slavimo", center: "star", sky: "snow", reward: "svichka", finale: "spivai" },
    { id: "velykden", culture: "Velykden, 'the Great Day', is Easter, the biggest feast of spring. A week before, on Willow Sunday, people bring pussy willow to church. On Easter morning families carry baskets with paska, pysanky (eggs decorated with wax and dyes), butter and cheese to be blessed. Everyone greets each other «Христос воскрес!» (Christ is risen!) and answers «Воістину воскрес!», and girls dance the old spring round dances, the hahilky.", tune: "fest-velykden", beat: 0.7895, first: 0.093, needs: { paska: 1, yaitse: 6, maslo: 2, syr: 2 }, greet: "khrystos_voskres", reply: "voistynu", center: "basket", sky: "spring", reward: "pysanka" }
  ],
